/* =========================================
   リセット & ベーススタイル
   ========================================= */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, sans-serif;

  /* カラーパレット */
  --color-primary: #3b82f6;
  --color-primary-dark: #1d4ed8;
  --color-primary-light: #eff6ff;
  --color-accent: #6366f1;
  --color-accent-subtle: #e0e7ff;
  --color-success: #10b981;
  --color-success-bg: #ecfdf5;
  --color-warning: #f59e0b;
  --color-warning-bg: #fffbeb;
  --color-danger: #ef4444;
  --color-text-main: #1e293b;
  --color-text-muted: #64748b;
  --color-border: #e2e8f0;
  --color-bg-base: #f8fafc;
  --color-bg-card: #ffffff;

  /* シャドウ */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.07), 0 4px 6px -4px rgba(0, 0, 0, 0.05);

  /* 角丸 */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-base);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* =========================================
   レイアウトコンテナ
   ========================================= */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

@media (min-width: 768px) {
  .app-container {
    padding: 32px 24px 64px;
    gap: 32px;
  }
}

/* =========================================
   ヘッダー
   ========================================= */
.dashboard-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 20px;
}

.header-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
}

@media (min-width: 640px) {
  .header-title {
    font-size: 1.875rem;
  }
}

.header-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-muted);
}

@media (min-width: 640px) {
  .header-subtitle {
    font-size: 0.95rem;
  }
}

/* =========================================
   サマリーカード
   ========================================= */
.summary-grid {
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 16px;
}

@media (min-width: 640px) {
  .summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .summary-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.summary-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.summary-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.summary-card-accent {
  background: linear-gradient(135deg, #ffffff 0%, var(--color-accent-subtle) 100%);
  border-color: #c7d2fe;
}

.summary-label {
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-muted);
}

.summary-value {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-text-main);
  letter-spacing: -0.03em;
  line-height: 1.2;
}

.summary-sub {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* =========================================
   操作パネル・ボタングループ
   ========================================= */
.controls-group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.control-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  user-select: none;
  transition: all 0.2s ease;
}

.control-btn:hover {
  background-color: #f1f5f9;
  color: var(--color-text-main);
  border-color: #cbd5e1;
}

.control-btn-active {
  background-color: var(--color-primary);
  color: #ffffff;
  border-color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.control-btn-active:hover {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  border-color: var(--color-primary-dark);
}

/* =========================================
   チャートカード
   ========================================= */
.chart-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

@media (min-width: 768px) {
  .chart-card {
    padding: 24px;
  }
}

.chart-card-header {
  display: flex;
  flex-direction: column;
  gap: 12px;
  justify-content: space-between;
  align-items: flex-start;
}

@media (min-width: 640px) {
  .chart-card-header {
    flex-direction: row;
    align-items: center;
  }
}

.chart-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.chart-container {
  width: 100%;
  height: 360px;
  position: relative;
}

@media (min-width: 768px) {
  .chart-container {
    height: 420px;
  }
}

/* =========================================
   凡例・ツールチップ要素
   ========================================= */
.legend-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

/* =========================================
   データテーブルカード & テーブル
   ========================================= */
.table-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

@media (min-width: 768px) {
  .table-card {
    padding: 24px;
  }
}

.reset-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-muted);
  background-color: var(--color-bg-base);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
}

.reset-btn:hover {
  background-color: #fee2e2;
  border-color: #fca5a5;
  color: var(--color-danger);
}

.table-wrapper {
  width: 100%;
  overflow: hidden;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
}

.sales-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

.sales-table th {
  background-color: #f8fafc;
  font-weight: 600;
  color: var(--color-text-muted);
  border-bottom: 1px solid var(--color-border);
  white-space: nowrap;
}

.th-cell {
  padding: 12px 16px;
}

.td-cell {
  padding: 10px 16px;
  border-bottom: 1px solid var(--color-border);
  color: var(--color-text-main);
  white-space: nowrap;
}

.sales-table tbody tr:last-child .td-cell {
  border-bottom: none;
}

.sales-table tbody tr:hover {
  background-color: #f1f5f9;
}

.td-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
}

/* 数値編集インプット */
.edit-input {
  width: 110px;
  padding: 6px 10px;
  font-size: 0.875rem;
  font-family: inherit;
  font-variant-numeric: tabular-nums;
  text-align: right;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: #ffffff;
  color: var(--color-text-main);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.edit-input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

/* =========================================
   ステータスバッジ
   ========================================= */
.badge-success {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  font-size: 0.75rem;
  font-weight: 600;
  color: #065f46;
  background-color: var(--color-success-bg);
  border: 1px solid #a7f3d0;
  border-radius: 9999px;
}

.badge-warning {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  font-size: 0.75rem;
  font-weight: 600;
  color: #92400e;
  background-color: var(--color-warning-bg);
  border: 1px solid #fde68a;
  border-radius: 9999px;
}

/**
 * 月別売上データインターフェース
 * 編集可能な売上実績（sales）と、マスター・比較対象の読み取り専用フィールドを分離定義
 */
export interface MonthlySalesData {
  readonly month: string;
  readonly monthNumber: number;
  sales: number;
  readonly target: number;
  readonly lastYearSales: number;
}

/**
 * 売上データ更新ペイロード
 */
export interface UpdateSalesPayload {
  monthNumber: number;
  sales: number;
}

/**
 * 年間集計・ダッシュボード統計情報
 * UI表示に必須な項目に加え、拡張用・詳細分析用の最低売上情報（オプショナル）を整理
 */
export interface SummaryStats {
  totalSales: number;
  averageSales: number;
  maxMonth: string;
  maxSales: number;
  minMonth?: string;
  minSales?: number;
  achievementRate: number;
}

/**
 * チャート表示オプション
 */
export interface ChartViewOptions {
  showTarget: boolean;
  showLastYear: boolean;
}

import { SummaryStats } from '../types';

interface SummaryCardsProps {
  stats: SummaryStats;
}

export default function SummaryCards({ stats }: SummaryCardsProps) {
  const formatYen = (amount: number) => {
    return `${Math.round(amount).toLocaleString('ja-JP')} 万円`;
  };

  const isAchieved = stats.achievementRate >= 100;

  return (
    <div className="summary-grid">
      <div className="summary-card">
        <span className="summary-label">年間総売上</span>
        <span className="summary-value">{formatYen(stats.totalSales)}</span>
        <span className="summary-sub">全12ヶ月の合計実績</span>
      </div>

      <div className="summary-card">
        <span className="summary-label">月平均売上</span>
        <span className="summary-value">{formatYen(stats.averageSales)}</span>
        <span className="summary-sub">月間ペース目安</span>
      </div>

      <div className="summary-card">
        <span className="summary-label">最高 / 最低売上月</span>
        <span className="summary-value">
          {stats.maxMonth}
          <span style={{ fontSize: '1rem', fontWeight: 500, color: 'var(--color-text-muted)', margin: '0 4px' }}>/</span>
          {stats.minMonth}
        </span>
        <span className="summary-sub">
          最高: {formatYen(stats.maxSales)} / 最低: {formatYen(stats.minSales)}
        </span>
      </div>

      <div
        className="summary-card summary-card-accent"
        style={
          !isAchieved
            ? {
                background: 'linear-gradient(135deg, #ffffff 0%, var(--color-warning-bg) 100%)',
                borderColor: '#fde68a'
              }
            : undefined
        }
      >
        <span className="summary-label">年間目標達成率</span>
        <span className="summary-value">{stats.achievementRate.toFixed(1)}%</span>
        <span className="summary-sub">
          {isAchieved
            ? '目標達成中'
            : `未達 (${(100 - stats.achievementRate).toFixed(1)}% 不足)`}
        </span>
      </div>
    </div>
  );
}

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Legend
} from 'recharts';
import { MonthlySalesData, ChartViewOptions } from '../types';

interface SalesBarChartProps {
  data: MonthlySalesData[];
  options: ChartViewOptions;
  onOptionsChange: (options: ChartViewOptions) => void;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    value?: unknown;
    dataKey?: string | number;
    name?: string;
    color?: string;
  }>;
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <div className="chart-tooltip">
        <p className="chart-tooltip-label">{label}</p>
        {payload.map((entry, index) => {
          let displayVal = '0 万円';
          if (typeof entry.value === 'number') {
            displayVal = `${entry.value.toLocaleString()} 万円`;
          } else if (typeof entry.value === 'string') {
            const parsed = Number(entry.value);
            displayVal = !isNaN(parsed) ? `${parsed.toLocaleString()} 万円` : `${entry.value} 万円`;
          } else if (
            Array.isArray(entry.value) &&
            entry.value.length > 0 &&
            typeof entry.value[0] === 'number'
          ) {
            displayVal = `${entry.value[0].toLocaleString()} 万円`;
          }

          return (
            <div key={`tooltip-item-${index}`} className="chart-tooltip-item">
              <span style={{ color: entry.color || 'var(--color-primary)' }}>● </span>
              <span style={{ color: 'var(--color-text-muted)' }}>{entry.name}: </span>
              <span style={{ fontWeight: 600, color: 'var(--color-text-main)' }}>
                {displayVal}
              </span>
            </div>
          );
        })}
      </div>
    );
  }
  return null;
};

export default function SalesBarChart({
  data = [],
  options,
  onOptionsChange
}: SalesBarChartProps) {
  const toggleTarget = () => {
    onOptionsChange({
      ...options,
      showTarget: !options.showTarget
    });
  };

  const toggleLastYear = () => {
    onOptionsChange({
      ...options,
      showLastYear: !options.showLastYear
    });
  };

  return (
    <div className="chart-card">
      <div className="chart-card-header">
        <h2 className="chart-title">月別売上推移グラフ</h2>
        <div className="controls-group">
          <button
            type="button"
            className={options.showTarget ? 'control-btn control-btn-active' : 'control-btn'}
            onClick={toggleTarget}
          >
            {options.showTarget ? '✓ 各月目標値を表示中' : '各月目標値を表示'}
          </button>
          <button
            type="button"
            className={options.showLastYear ? 'control-btn control-btn-active' : 'control-btn'}
            onClick={toggleLastYear}
          >
            {options.showLastYear ? '✓ 前年実績を表示中' : '前年実績を表示'}
          </button>
        </div>
      </div>

      <div className="chart-container">
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart
            data={data}
            margin={{ top: 20, right: 20, left: 0, bottom: 10 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
            <XAxis
              dataKey="month"
              stroke="#64748b"
              fontSize={12}
              tickLine={false}
              axisLine={{ stroke: '#e2e8f0' }}
            />
            <YAxis
              stroke="#64748b"
              fontSize={12}
              tickLine={false}
              axisLine={{ stroke: '#e2e8f0' }}
              tickFormatter={(value) => `${value}万`}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend
              wrapperStyle={{ paddingTop: '12px' }}
              iconType="circle"
              iconSize={8}
            />

            {options.showLastYear && (
              <Bar
                dataKey="lastYearSales"
                name="前年売上"
                fill="#94a3b8"
                radius={[4, 4, 0, 0]}
                maxBarSize={32}
              />
            )}

            <Bar
              dataKey="sales"
              name="今年売上"
              fill="#3b82f6"
              radius={[4, 4, 0, 0]}
              maxBarSize={32}
            />

            {options.showTarget && (
              <Line
                type="monotone"
                dataKey="target"
                name="目標売上"
                stroke="#ef4444"
                strokeWidth={2.5}
                dot={{ r: 4, fill: '#ef4444', strokeWidth: 0 }}
                activeDot={{ r: 6 }}
              />
            )}
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { useState, useEffect, ChangeEvent, KeyboardEvent } from 'react';
import { MonthlySalesData } from '../types';

interface DataTableProps {
  data: MonthlySalesData[];
  onUpdateSales: (monthNumber: number, newSales: number) => void;
  onResetData: () => void;
}

export default function DataTable({
  data = [],
  onUpdateSales,
  onResetData
}: DataTableProps) {
  const [inputMap, setInputMap] = useState<Record<number, string>>(() => {
    const initial: Record<number, string> = {};
    data.forEach((item) => {
      initial[item.monthNumber] = String(item.sales);
    });
    return initial;
  });

  useEffect(() => {
    const updated: Record<number, string> = {};
    data.forEach((item) => {
      updated[item.monthNumber] = String(item.sales);
    });
    setInputMap(updated);
  }, [data]);

  const handleInputChange = (
    e: ChangeEvent<HTMLInputElement>,
    monthNumber: number
  ) => {
    const val = e.target.value;

    if (val === '') {
      setInputMap((prev) => ({ ...prev, [monthNumber]: '' }));
      return;
    }

    if (!/^\d+$/.test(val)) {
      return;
    }

    const parsed = parseInt(val, 10);
    if (!isNaN(parsed) && parsed >= 0) {
      setInputMap((prev) => ({ ...prev, [monthNumber]: String(parsed) }));
      onUpdateSales(monthNumber, parsed);
    }
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'e' || e.key === 'E' || e.key === '+' || e.key === '-' || e.key === '.') {
      e.preventDefault();
    }
  };

  const handleBlur = (monthNumber: number) => {
    const currentVal = inputMap[monthNumber];
    if (currentVal === '' || isNaN(Number(currentVal))) {
      setInputMap((prev) => ({ ...prev, [monthNumber]: '0' }));
      onUpdateSales(monthNumber, 0);
    }
  };

  return (
    <div className="table-card">
      <div className="chart-card-header">
        <h2 className="chart-title">月別売上データ一覧 & 編集</h2>
        <button
          type="button"
          className="reset-btn"
          onClick={() => onResetData?.()}
        >
          初期値にリセット
        </button>
      </div>

      <div className="table-wrapper">
        <table className="sales-table">
          <thead>
            <tr>
              <th className="th-cell">対象月</th>
              <th className="th-cell td-num">
                今年売上 (万円)
                <span style={{ fontSize: '0.75rem', fontWeight: 600, color: 'var(--color-primary)', marginLeft: '6px' }}>
                  [編集可]
                </span>
              </th>
              <th className="th-cell td-num">目標売上 (万円)</th>
              <th className="th-cell td-num">前年売上 (万円)</th>
              <th className="th-cell td-num">目標達成率</th>
              <th className="th-cell td-num">前年比</th>
              <th className="th-cell" style={{ textAlign: 'center' }}>状態</th>
            </tr>
          </thead>
          <tbody>
            {data.map((item) => {
              const achievement = item.target > 0 ? (item.sales / item.target) * 100 : 0;
              const yoy = item.lastYearSales > 0 ? (item.sales / item.lastYearSales) * 100 : 0;
              const isAchieved = achievement >= 100;
              const inputValue = inputMap[item.monthNumber] ?? String(item.sales);

              return (
                <tr key={item.monthNumber}>
                  <td className="td-cell" style={{ fontWeight: 600 }}>
                    {item.month}
                  </td>
                  <td className="td-cell td-num">
                    <input
                      type="number"
                      min="0"
                      step="1"
                      className="edit-input"
                      value={inputValue}
                      onChange={(e) => handleInputChange(e, item.monthNumber)}
                      onKeyDown={handleKeyDown}
                      onBlur={() => handleBlur(item.monthNumber)}
                      aria-label={`${item.month} 売上編集`}
                    />
                  </td>
                  <td className="td-cell td-num">
                    {item.target.toLocaleString()} 万円
                  </td>
                  <td className="td-cell td-num">
                    {item.lastYearSales.toLocaleString()} 万円
                  </td>
                  <td className="td-cell td-num" style={{ fontWeight: 600 }}>
                    {achievement.toFixed(1)}%
                  </td>
                  <td className="td-cell td-num">
                    {yoy.toFixed(1)}%
                  </td>
                  <td className="td-cell" style={{ textAlign: 'center' }}>
                    <span className={isAchieved ? 'badge-success' : 'badge-warning'}>
                      {isAchieved ? '達成' : '未達'}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { MonthlySalesData, SummaryStats, ChartViewOptions } from './types';
import SummaryCards from './components/SummaryCards';
import SalesBarChart from './components/SalesBarChart';
import DataTable from './components/DataTable';

const STORAGE_KEY = 'monthly_sales_dashboard_data';
const MAX_SALES_LIMIT = 999999;
const MIN_SALES_LIMIT = 0;

const INITIAL_SALES_DATA: MonthlySalesData[] = [
  { month: '1月', monthNumber: 1, sales: 420, target: 400, lastYearSales: 380 },
  { month: '2月', monthNumber: 2, sales: 380, target: 400, lastYearSales: 350 },
  { month: '3月', monthNumber: 3, sales: 550, target: 500, lastYearSales: 480 },
  { month: '4月', monthNumber: 4, sales: 490, target: 450, lastYearSales: 430 },
  { month: '5月', monthNumber: 5, sales: 460, target: 450, lastYearSales: 440 },
  { month: '6月', monthNumber: 6, sales: 520, target: 480, lastYearSales: 490 },
  { month: '7月', monthNumber: 7, sales: 580, target: 550, lastYearSales: 510 },
  { month: '8月', monthNumber: 8, sales: 540, target: 520, lastYearSales: 500 },
  { month: '9月', monthNumber: 9, sales: 480, target: 480, lastYearSales: 460 },
  { month: '10月', monthNumber: 10, sales: 530, target: 500, lastYearSales: 470 },
  { month: '11月', monthNumber: 11, sales: 590, target: 550, lastYearSales: 530 },
  { month: '12月', monthNumber: 12, sales: 680, target: 600, lastYearSales: 610 }
];

const getClonedInitialData = (): MonthlySalesData[] => {
  return INITIAL_SALES_DATA.map((item) => ({ ...item }));
};

const loadInitialSalesData = (): MonthlySalesData[] => {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed) && parsed.length === INITIAL_SALES_DATA.length) {
        return parsed;
      }
    }
  } catch {
    // localStorageアクセスエラーやJSON破損時はフォールバック
  }
  return getClonedInitialData();
};

export default function App() {
  const [salesData, setSalesData] = useState<MonthlySalesData[]>(loadInitialSalesData);
  const [chartOptions, setChartOptions] = useState<ChartViewOptions>({
    showTarget: true,
    showLastYear: true
  });

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(salesData));
    } catch {
      // localStorage容量超過などの書き込みエラー抑制
    }
  }, [salesData]);

  const handleUpdateSales = (monthNumber: number, newSales: number) => {
    const sanitizedSales = Math.min(
      Math.max(MIN_SALES_LIMIT, Math.floor(newSales)),
      MAX_SALES_LIMIT
    );
    setSalesData((prev) =>
      prev.map((item) =>
        item.monthNumber === monthNumber ? { ...item, sales: sanitizedSales } : item
      )
    );
  };

  const handleResetData = () => {
    const freshData = getClonedInitialData();
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch {
      // localStorage削除エラー抑制
    }
    setSalesData(freshData);
  };

  const summaryStats: SummaryStats = useMemo(() => {
    if (salesData.length === 0) {
      return {
        totalSales: 0,
        averageSales: 0,
        maxMonth: '-',
        maxSales: 0,
        minMonth: '-',
        minSales: 0,
        achievementRate: 0
      };
    }

    let total = 0;
    let targetTotal = 0;
    let max = salesData[0];
    let min = salesData[0];

    salesData.forEach((item) => {
      total += item.sales;
      targetTotal += item.target;
      if (item.sales > max.sales) max = item;
      if (item.sales < min.sales) min = item;
    });

    const average = total / salesData.length;
    const rate = targetTotal > 0 ? (total / targetTotal) * 100 : 0;

    return {
      totalSales: total,
      averageSales: average,
      maxMonth: max.month,
      maxSales: max.sales,
      minMonth: min.month,
      minSales: min.sales,
      achievementRate: rate
    };
  }, [salesData]);

  return (
    <div className="app-container">
      <header className="dashboard-header">
        <h1 className="header-title">月別売上推移ダッシュボード</h1>
        <p className="header-subtitle">
          1月〜12月の売上実績・目標達成率・前年比較をリアルタイムに確認・シミュレーションできます。
        </p>
      </header>

      <SummaryCards stats={summaryStats} />

      <SalesBarChart
        data={salesData}
        options={chartOptions}
        onOptionsChange={setChartOptions}
      />

      <DataTable
        data={salesData}
        onUpdateSales={handleUpdateSales}
        onResetData={handleResetData}
      />
    </div>
  );
}
